import os
import torch


class Config:
    # --------------------------------------------------------------------------
    # Reproducibility & Hardware
    # --------------------------------------------------------------------------
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    # Utilizing 12 vCPUs for data loading
    NUM_WORKERS = 12

    # --------------------------------------------------------------------------
    # File Paths
    # --------------------------------------------------------------------------
    # Metadata paths (Parquet files generated by previous steps)
    TRAIN_DATA_PATH = "./metadata/train.parquet"
    VAL_DATA_PATH = "./metadata/val.parquet"
    TEST_DATA_PATH = "./metadata/test.parquet"

    # Sample submission for format reference
    SAMPLE_SUBMISSION_PATH = "./input/sample_submission.csv"

    # Working Directory for this specific idea (idea_18)
    WORKING_DIR = "./working/idea_18"

    # Cache directory for processed data (numpy/parquet)
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")

    # Model checkpoint location
    MODEL_CHECKPOINT_PATH = os.path.join(WORKING_DIR, "model.pth")

    # Submission output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Create necessary directories
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(CACHE_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # --------------------------------------------------------------------------
    # Data Configuration
    # --------------------------------------------------------------------------
    ID_COL = "Id"
    TARGET_COL = "Cover_Type"

    # Forest Cover Type has 7 classes (1-7).
    # We will map them to 0-6 internally if necessary, but output 1-7.
    NUM_CLASSES = 7

    # Raw Continuous Features (to be standardized)
    # Using standard dataset names inferred from analysis
    CONTINUOUS_FEATURES = [
        "Elevation",
        "Aspect",
        "Slope",
        "Horizontal_Distance_To_Hydrology",
        "Vertical_Distance_To_Hydrology",
        "Horizontal_Distance_To_Roadways",
        "Hillshade_9am",
        "Hillshade_Noon",
        "Hillshade_3pm",
        "Horizontal_Distance_To_Fire_Points",
    ]

    # Binary Features (One-Hot Encoded in raw data)
    # Wilderness Areas (4 columns)
    WILDERNESS_FEATURES = [f"Wilderness_Area{i}" for i in range(1, 5)]
    # Soil Types (40 columns)
    SOIL_FEATURES = [f"Soil_Type{i}" for i in range(1, 41)]

    BINARY_FEATURES = WILDERNESS_FEATURES + SOIL_FEATURES

    # --------------------------------------------------------------------------
    # Model Hyperparameters
    # --------------------------------------------------------------------------
    # Parallel Low-Rank DCN-ResNet
    DCN_RANK = 16  # Rank for the factorized cross layer
    RESNET_WIDTH = 512  # Width of the ResNet backbone

    # --------------------------------------------------------------------------
    # Training Hyperparameters
    # --------------------------------------------------------------------------
    BATCH_SIZE = 4096
    EPOCHS = 60
    LEARNING_RATE = 1e-3  # Initial LR for Cosine Annealing
    WEIGHT_DECAY = 1e-4  # Regularization
    PATIENCE = 10  # Early stopping patience
